#include <stdlib.h>

struct Stack { int* data; int size; };

void push(struct Stack* s, int v) {
    s->data[s->size++] = v;
}

int main(void) {
    struct Stack s;
    s.data = malloc(10 * sizeof(int));
    s.size = 0;
    push(&s, 42);
    free(s.data);   // you must remember
}

